sql.where:
a.status = 'OPENED'

    AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR a.account_no LIKE CONCAT('%', #{keyword}, '%'))


    AND EXISTS (
    SELECT 1 FROM domestic_stock_balance dsb2
    WHERE dsb2.account_id = a.account_id AND dsb2.status = #{status}
    )


    AND EXISTS (
    SELECT 1 FROM domestic_stock_balance dsb2
    WHERE dsb2.account_id = a.account_id AND dsb2.status IN ('TRADE_RESTRICTED', 'TRADE_SUSPENDED')
    )


    AND NOT EXISTS (
    SELECT 1 FROM domestic_stock_balance dsb2
    WHERE dsb2.account_id = a.account_id AND dsb2.status IN ('TRADE_RESTRICTED', 'TRADE_SUSPENDED')
    )


    AND a.account_id IN

        #{id}



    AND EXISTS (
    SELECT 1 FROM domestic_stock_balance dsb2
    WHERE dsb2.account_id = a.account_id
    AND dsb2.last_purchase_date >= #{recentBuySinceDate}
    AND dsb2.status NOT IN ('SOLD_OUT', 'TERMINATED')
    )


    AND NOT EXISTS (
    SELECT 1 FROM domestic_stock_balance dsb2
    WHERE dsb2.account_id = a.account_id
    AND dsb2.last_purchase_date >= #{recentBuySinceDate}
    AND dsb2.status NOT IN ('SOLD_OUT', 'TERMINATED')
    )

mapper.select:
SELECT



GROUP BY a.account_id, a.account_no, c.name, a.amount
ORDER BY ${orderBy}
LIMIT #{size} OFFSET #{offset}

SELECT


WHERE a.account_id = #{accountId}
GROUP BY a.account_id, a.account_no, c.name, a.amount
